-- Generated by schema.py. SQLite / PostgreSQL compatible.

CREATE TABLE merchants (
  merchant_id TEXT NOT NULL,
  merchant_name TEXT NOT NULL,
  country TEXT NOT NULL CHECK (country IN ('DE', 'ES', 'FR', 'GB', 'IE', 'JP', 'NL', 'US')),
  settlement_currency TEXT NOT NULL CHECK (settlement_currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  category TEXT NOT NULL CHECK (category IN ('RETAIL', 'DIGITAL_GOODS', 'TRAVEL', 'FOOD_DELIVERY', 'SUBSCRIPTIONS', 'ELECTRONICS')),
  fee_rate_pct NUMERIC(18,2) NOT NULL,
  fixed_fee NUMERIC(18,2) NOT NULL,
  settlement_delay_days INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('ACTIVE', 'SUSPENDED', 'CLOSED')),
  onboarded_date TEXT NOT NULL,
  fee_effective_from TEXT NOT NULL,
  PRIMARY KEY (merchant_id)
);

CREATE TABLE payment_orders (
  payment_id TEXT NOT NULL,
  merchant_id TEXT NOT NULL,
  customer_ref TEXT NOT NULL,
  amount NUMERIC(18,2) NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  created_at TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('CAPTURED', 'PARTIALLY_REFUNDED', 'REFUNDED', 'FAILED')),
  captured_amount NUMERIC(18,2) NOT NULL,
  refunded_amount NUMERIC(18,2) NOT NULL,
  attempt_count INTEGER NOT NULL,
  PRIMARY KEY (payment_id),
  FOREIGN KEY (merchant_id) REFERENCES merchants(merchant_id)
);

CREATE TABLE payment_attempts (
  attempt_id TEXT NOT NULL,
  payment_id TEXT NOT NULL,
  attempt_no INTEGER NOT NULL,
  attempted_at TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('SUCCEEDED', 'DECLINED', 'ERROR')),
  decline_code TEXT CHECK (decline_code IN ('INSUFFICIENT_FUNDS', 'DO_NOT_HONOR', 'EXPIRED_CARD', 'SUSPECTED_FRAUD', 'INVALID_CVV', 'PROCESSOR_TIMEOUT')),
  payment_method TEXT NOT NULL CHECK (payment_method IN ('CARD_VISA', 'CARD_MASTERCARD', 'CARD_AMEX')),
  PRIMARY KEY (attempt_id),
  FOREIGN KEY (payment_id) REFERENCES payment_orders(payment_id)
);

CREATE TABLE processor_events (
  ingest_id TEXT NOT NULL,
  delivery_id TEXT NOT NULL,
  event_id TEXT NOT NULL,
  payment_id TEXT NOT NULL,
  attempt_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('AUTHORIZED', 'CAPTURED', 'REFUNDED', 'FAILED')),
  amount NUMERIC(18,2) NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  event_at TEXT NOT NULL,
  received_at TEXT NOT NULL,
  PRIMARY KEY (ingest_id),
  FOREIGN KEY (payment_id) REFERENCES payment_orders(payment_id),
  FOREIGN KEY (attempt_id) REFERENCES payment_attempts(attempt_id)
);

CREATE TABLE settlement_batches (
  batch_id TEXT NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  settlement_date TEXT NOT NULL,
  line_count INTEGER NOT NULL,
  capture_count INTEGER NOT NULL,
  refund_count INTEGER NOT NULL,
  gross_captured NUMERIC(18,2) NOT NULL,
  gross_refunded NUMERIC(18,2) NOT NULL,
  fee_total NUMERIC(18,2) NOT NULL,
  net_amount NUMERIC(18,2) NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('OPEN', 'CLOSED')),
  PRIMARY KEY (batch_id)
);

CREATE TABLE settlement_lines (
  settlement_line_id TEXT NOT NULL,
  batch_id TEXT NOT NULL,
  event_id TEXT NOT NULL,
  payment_id TEXT NOT NULL,
  line_type TEXT NOT NULL CHECK (line_type IN ('CAPTURE', 'REFUND')),
  gross_amount NUMERIC(18,2) NOT NULL,
  fee_amount NUMERIC(18,2) NOT NULL,
  net_amount NUMERIC(18,2) NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  event_date TEXT NOT NULL,
  PRIMARY KEY (settlement_line_id),
  FOREIGN KEY (batch_id) REFERENCES settlement_batches(batch_id),
  FOREIGN KEY (payment_id) REFERENCES payment_orders(payment_id)
);

CREATE TABLE bank_statement_lines (
  bank_line_id TEXT NOT NULL,
  account_id TEXT NOT NULL CHECK (account_id IN ('ACC-USD-001', 'ACC-EUR-001', 'ACC-GBP-001', 'ACC-JPY-001')),
  value_date TEXT NOT NULL,
  amount NUMERIC(18,2) NOT NULL,
  currency TEXT NOT NULL CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  direction TEXT NOT NULL CHECK (direction IN ('CREDIT', 'DEBIT')),
  counterparty TEXT NOT NULL,
  reference TEXT,
  description TEXT NOT NULL,
  PRIMARY KEY (bank_line_id)
);

CREATE TABLE event_dedup_log (
  dedup_id TEXT NOT NULL,
  ingest_id TEXT NOT NULL,
  event_id TEXT NOT NULL,
  duplicate_of_ingest_id TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('DUPLICATE_WEBHOOK', 'DUPLICATE_INGESTION')),
  payload_identical TEXT NOT NULL CHECK (payload_identical IN ('Y', 'N')),
  decision TEXT NOT NULL CHECK (decision IN ('IGNORED_IDEMPOTENT')),
  PRIMARY KEY (dedup_id),
  FOREIGN KEY (ingest_id) REFERENCES processor_events(ingest_id),
  FOREIGN KEY (duplicate_of_ingest_id) REFERENCES processor_events(ingest_id)
);

CREATE TABLE reconciliation_matches (
  match_id TEXT NOT NULL,
  match_level TEXT NOT NULL CHECK (match_level IN ('EVENT_TO_SETTLEMENT', 'BATCH_TO_BANK')),
  event_id TEXT,
  settlement_line_id TEXT,
  batch_id TEXT,
  bank_line_id TEXT,
  match_status TEXT NOT NULL CHECK (match_status IN ('MATCHED', 'MATCHED_WITH_TOLERANCE', 'PARTIAL', 'UNMATCHED', 'DUPLICATE', 'OUT_OF_SCOPE')),
  match_method TEXT NOT NULL CHECK (match_method IN ('EVENT_ID', 'REFERENCE', 'AMOUNT_CURRENCY_DATE', 'COUNTERPARTY_FILTER', 'NONE')),
  expected_amount NUMERIC(18,2),
  actual_amount NUMERIC(18,2),
  difference NUMERIC(18,2),
  currency TEXT CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  tolerance NUMERIC(18,2),
  matched_on TEXT NOT NULL,
  PRIMARY KEY (match_id),
  FOREIGN KEY (settlement_line_id) REFERENCES settlement_lines(settlement_line_id),
  FOREIGN KEY (batch_id) REFERENCES settlement_batches(batch_id),
  FOREIGN KEY (bank_line_id) REFERENCES bank_statement_lines(bank_line_id)
);

CREATE TABLE exceptions (
  exception_id TEXT NOT NULL,
  exception_type TEXT NOT NULL CHECK (exception_type IN ('MISSING_FROM_SETTLEMENT', 'DUPLICATE_SETTLEMENT_LINE', 'ORPHAN_SETTLEMENT_LINE', 'LINE_AMOUNT_MISMATCH', 'LINE_CURRENCY_MISMATCH', 'LATE_SETTLEMENT', 'REFUND_BEFORE_CAPTURE', 'EVENT_PAYLOAD_CONFLICT', 'FEE_DIFFERENCE', 'AMOUNT_MISMATCH', 'CURRENCY_MISMATCH', 'DATE_OUT_OF_WINDOW', 'DUPLICATE_PAYOUT', 'UNMATCHED_BANK_LINE', 'AMBIGUOUS_BANK_MATCH', 'MISSING_PAYOUT')),
  severity TEXT NOT NULL CHECK (severity IN ('LOW', 'MEDIUM', 'HIGH')),
  entity_type TEXT NOT NULL CHECK (entity_type IN ('ProcessorEvent', 'SettlementLine', 'SettlementBatch', 'BankStatementLine')),
  entity_id TEXT NOT NULL,
  related_ids TEXT,
  match_id TEXT,
  amount_difference NUMERIC(18,2),
  currency TEXT CHECK (currency IN ('USD', 'EUR', 'GBP', 'JPY')),
  rule TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('OPEN')),
  created_at TEXT NOT NULL,
  PRIMARY KEY (exception_id),
  FOREIGN KEY (match_id) REFERENCES reconciliation_matches(match_id)
);

CREATE TABLE resolutions (
  resolution_id TEXT NOT NULL,
  exception_id TEXT NOT NULL,
  step_no INTEGER NOT NULL,
  actor_role TEXT NOT NULL CHECK (actor_role IN ('operations_analyst', 'risk_compliance_reviewer', 'system_administrator')),
  action TEXT NOT NULL CHECK (action IN ('POST_FEE_ADJUSTMENT', 'RAISE_PROCESSOR_CLAIM', 'CHASE_PAYOUT', 'INVESTIGATE', 'ESCALATE', 'COMPLIANCE_REVIEW')),
  resulting_status TEXT NOT NULL CHECK (resulting_status IN ('RESOLVED', 'PENDING_PROCESSOR', 'IN_REVIEW', 'ESCALATED', 'UNDER_COMPLIANCE_REVIEW')),
  recorded_at TEXT NOT NULL,
  note TEXT NOT NULL,
  PRIMARY KEY (resolution_id),
  FOREIGN KEY (exception_id) REFERENCES exceptions(exception_id)
);


-- Current status of each exception = its latest resolution step (history is never overwritten)
CREATE VIEW exception_current_status AS
SELECT e.exception_id, e.exception_type, e.severity, e.entity_type, e.entity_id,
       r.resulting_status AS current_status, r.actor_role AS last_actor
FROM exceptions e
LEFT JOIN resolutions r
  ON r.exception_id = e.exception_id
 AND r.step_no = (SELECT MAX(step_no) FROM resolutions r2 WHERE r2.exception_id = e.exception_id);

-- Processor events after idempotent deduplication
CREATE VIEW processor_events_unique AS
SELECT * FROM processor_events
WHERE ingest_id NOT IN (SELECT ingest_id FROM event_dedup_log);
